mapper.select:
SELECT apr40_download_history_id                                    AS download_history_id
     , apr40_appr_id                                                AS appr_id
     , TO_CHAR(apr40_reg_date, 'YYYY-MM-DD HH24:MI:SS')             AS reg_date_string
     , apr01_title                                                  AS title
     , f_emp_kor_nm(apr40_person_id)                                AS person_name
  FROM apr40_download_history
       INNER JOIN apr01_appr ON apr40_appr_id = apr01_appr_id AND apr01_company_id = #{c.companyId}
 WHERE 1=1
   AND f_trunc(apr40_reg_date) BETWEEN #{c.startDate} AND #{c.closeDate}
   AND UPPER(CONCAT(apr01_title, f_emp_kor_nm(apr40_person_id))) LIKE UPPER(#{c.searchText})
 ORDER BY apr40_reg_date DESC, apr01_title, f_emp_kor_nm(apr40_person_id)
 LIMIT #{c.limit}
OFFSET #{c.offset}

SELECT count(apr40_download_history.*)
  FROM apr40_download_history
       INNER JOIN apr01_appr ON apr40_appr_id = apr01_appr_id AND apr01_company_id = #{c.companyId}
 WHERE 1=1
   AND f_trunc(apr40_reg_date) BETWEEN #{c.startDate} AND #{c.closeDate}
   AND UPPER(CONCAT(apr01_title, f_emp_kor_nm(apr40_person_id))) LIKE UPPER(#{c.searchText})

mapper.insert:
INSERT INTO apr40_download_history (apr40_download_history_id, apr40_company_id, apr40_person_id, apr40_appr_id, apr40_reg_date)
SELECT f_create_seq()
     , #{companyId}
     , #{personId}
     , #{apprId}
     , f_sysdate()
